import{_ as t,o,c as n,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/LOOP.md","filePath":"manual-en/LOOP.md","lastUpdated":1785684581000}'),i={name:"manual-en/LOOP.md"};function s(r,e,d,c,l,h){return o(),n("div",null,[...e[0]||(e[0]=[a(`<h3 id="_14-5-loop" tabindex="-1">14.5 LOOP <a class="header-anchor" href="#_14-5-loop" aria-label="Permalink to &quot;14.5 LOOP&quot;">​</a></h3><pre><code>LOOP [index_var=start TO end [BY incr]] [IF condition].
        …
END LOOP [IF condition].
</code></pre><p><code>LOOP</code> iterates a group of commands. A number of termination options are offered.</p><p>Specify index_var to make that variable count from one value to another by a particular increment. index_var must be a pre-existing numeric variable. start, end, and incr are numeric expressions (see <a href="./Expressions">Expressions</a>.)</p><p>During the first iteration, index_var is set to the value of start. During each successive iteration, index_var is increased by the value of incr. If end &gt; start, then the loop terminates when index_var &gt; end; otherwise it terminates when index_var &lt; end. If incr is not specified then it defaults to +1 or -1 as appropriate.</p><p>If end &gt; start and incr &lt; 0, or if end &lt; start and incr &gt; 0, then the loop is never executed. index_var is nevertheless set to the value of start.</p><p>Modifying index_var within the loop is allowed, but it has no effect on the value of index_var in the next iteration.</p><p>Specify a boolean expression for the condition on <code>LOOP</code> to cause the loop to be executed only if the condition is true. If the condition is false or missing before the loop contents are executed the first time, the loop contents are not executed at all.</p><p>If index and condition clauses are both present on <code>LOOP</code>, the index variable is always set before the condition is evaluated. Thus, a condition that makes use of the index variable will always see the index value to be used in the next execution of the body.</p><p>Specify a boolean expression for the condition on <code>END LOOP</code> to cause the loop to terminate if the condition is true after the enclosed code block is executed. The condition is evaluated at the end of the loop, not at the beginning, so that the body of a loop with only a condition on <code>END LOOP</code> will always execute at least once.</p><p>If the index clause is not present, then the global <code>MXLOOPS</code> setting, which defaults to 40, limits the number of iterations (see <a href="./SET#SET-MXLOOPS">SET MXLOOPS</a>).</p><p><code>BREAK</code> also terminates <code>LOOP</code> execution (see <a href="./BREAK">BREAK</a>).</p><p>Loop index variables are by default reset to system-missing from one case to another, not left, unless a scratch variable is used as index. When loops are nested, this is usually undesired behavior, which can be corrected with <code>LEAVE</code> (see <a href="./LEAVE">LEAVE</a>) or by using a scratch variable as the loop index.</p><p>When <code>LOOP</code> or <code>END LOOP</code> is specified following <code>TEMPORARY</code> (see <a href="./TEMPORARY">TEMPORARY</a>), the <code>LAG</code> function may not be used (see <a href="./Miscellaneous-Functions#LAG">LAG</a>).</p>`,14)])])}const u=t(i,[["render",s]]);export{f as __pageData,u as default};
